//! The FFI tier table: `tiers.tsv`, generated by WinuxCmd at build
//! time from the audited manifest (DESIGN §6 R1–R7) and shipped in
//! the version directory beside `winuxcore.dll`. The host treats
//! the table as data of the DLL's own version — it is parsed, never
//! hand-edited, and a name absent from the table is unclassified
//! (spawn), exactly as the generator emits it.
//!
//! Format (tab-separated, `#` comments, one header row):
//! `command <TAB> tier <TAB> fallback_shapes <TAB> note`, with
//! tier ∈ `tier1 | tier2 | conditional | never | spawn`. The
//! `# winuxcmd-version:` header line carries the producing
//! WinuxCmd version, which the status face reports as the loaded
//! table's provenance.

use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    /// DESIGN §6.1: the simulated-layer retirement surface. FFI
    /// takes the baton only after the tier-1 differential gate;
    /// until then the route classifier keeps these on emulation
    /// (see `route::TIER1_FFI_CLAIMABLE`).
    Tier1,
    /// DESIGN §6.2: the true spawn-saving surface — the only tier
    /// the FFI route may claim.
    Tier2,
    /// DESIGN §6.4: named prerequisites outstanding (signal
    /// save/restore, console-layer routing, env-borrow proof…).
    /// Not claimable.
    Conditional,
    /// DESIGN §6.3: never FFI (interactive, long-running, the
    /// tree-managing `wpm`, console-state mutators).
    Never,
    /// Unclassified: R1–R7 audit pending. Spawn.
    Spawn,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TierRow {
    pub tier: Tier,
    /// Argument shapes that fall back to spawn for that call even
    /// when the command is FFI-eligible (`-` in the table = none).
    pub fallback_shapes: Vec<String>,
    pub note: String,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct TierTable {
    /// From the `# winuxcmd-version:` header line.
    pub winuxcmd_version: Option<String>,
    rows: HashMap<String, TierRow>,
}

impl TierTable {
    pub fn parse(text: &str) -> Result<Self, String> {
        let mut table = TierTable::default();
        for (index, line) in text.lines().enumerate() {
            let line = line.strip_suffix('\r').unwrap_or(line);
            if line.is_empty() {
                continue;
            }
            if let Some(comment) = line.strip_prefix('#') {
                if let Some(version) = comment.trim().strip_prefix("winuxcmd-version:") {
                    table.winuxcmd_version = Some(version.trim().to_string());
                }
                continue;
            }
            if line.starts_with("command\t") {
                continue; // header row
            }
            let mut parts = line.split('\t');
            let (Some(name), Some(tier), Some(shapes)) = (parts.next(), parts.next(), parts.next())
            else {
                return Err(format!("tiers.tsv line {}: too few columns", index + 1));
            };
            let tier = match tier {
                "tier1" => Tier::Tier1,
                "tier2" => Tier::Tier2,
                "conditional" => Tier::Conditional,
                "never" => Tier::Never,
                "spawn" => Tier::Spawn,
                other => {
                    return Err(format!(
                        "tiers.tsv line {}: unknown tier {other:?}",
                        index + 1
                    ))
                }
            };
            let fallback_shapes = if shapes == "-" {
                Vec::new()
            } else {
                shapes
                    .split(',')
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                    .map(str::to_string)
                    .collect()
            };
            let note = parts.collect::<Vec<_>>().join("\t");
            table.rows.insert(
                name.to_string(),
                TierRow {
                    tier,
                    fallback_shapes,
                    note,
                },
            );
        }
        Ok(table)
    }

    /// Row for a command name: exact match first, then the
    /// ASCII-lowercase spelling (Windows command resolution is
    /// case-insensitive; the table itself is lowercase).
    pub fn lookup(&self, name: &str) -> Option<&TierRow> {
        if let Some(row) = self.rows.get(name) {
            return Some(row);
        }
        let lowered = name.to_ascii_lowercase();
        if lowered != name {
            return self.rows.get(&lowered);
        }
        None
    }

    /// The canonical (table-spelled) name for a lookup, used as
    /// the ABI `applet` token: a routing token, not a user
    /// argument — argv never carries it (the ABI's argv excludes
    /// the name), so normalizing its case rewrites nothing the
    /// user typed.
    pub fn canonical_name(&self, name: &str) -> Option<String> {
        if self.rows.contains_key(name) {
            return Some(name.to_string());
        }
        let lowered = name.to_ascii_lowercase();
        if self.rows.contains_key(&lowered) {
            return Some(lowered);
        }
        None
    }

    pub fn contains(&self, name: &str) -> bool {
        self.lookup(name).is_some()
    }

    pub fn len(&self) -> usize {
        self.rows.len()
    }

    pub fn is_empty(&self) -> bool {
        self.rows.is_empty()
    }

    /// All names carrying a given tier, sorted (census/status use).
    pub fn names_with_tier(&self, tier: Tier) -> Vec<&str> {
        let mut names: Vec<&str> = self
            .rows
            .iter()
            .filter(|(_, row)| row.tier == tier)
            .map(|(name, _)| name.as_str())
            .collect();
        names.sort_unstable();
        names
    }
}

/// Whether one of the row's fallback shapes matches this call's
/// arguments. A shape written as a short flag (`-i`) also matches
/// flag clusters (`-ri`), per the manifest's own rule; any other
/// shape matches an argument byte-for-byte. Returns the matched
/// shape for the route log.
pub fn matching_fallback_shape<'a>(shapes: &'a [String], args: &[String]) -> Option<&'a str> {
    for shape in shapes {
        let bytes = shape.as_bytes();
        let is_short_flag = bytes.len() == 2 && bytes[0] == b'-' && bytes[1] != b'-';
        for arg in args {
            if is_short_flag {
                let arg_bytes = arg.as_bytes();
                if arg_bytes.len() >= 2
                    && arg_bytes[0] == b'-'
                    && arg_bytes[1] != b'-'
                    && !arg.starts_with("--")
                {
                    // Cluster: the letters between '-' and any '='.
                    let cluster = arg[1..].split('=').next().unwrap_or("");
                    if cluster.bytes().any(|b| b == bytes[1]) {
                        return Some(shape.as_str());
                    }
                }
            } else if arg == shape {
                return Some(shape.as_str());
            }
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "# winuxcore FFI tier table (generated at build time; do not edit)\n\
# winuxcmd-version: 1.2.0-dev\n\
# source-manifest: src/ffi/tiers-manifest.tsv\n\
command\ttier\tfallback_shapes\tnote\n\
cp\ttier1\t-\tTier-1 note\n\
rm\ttier1\t-i,-I\tInteractive shapes\n\
grep\ttier2\t--line-buffered\tTier-2 sample\n\
tee\tconditional\t-\tBlocked\n\
wpm\tnever\t-\tManages the tree\n\
arch\tspawn\t-\tunclassified: R1-R7 audit pending\n";

    #[test]
    fn parses_generated_table() {
        let table = TierTable::parse(SAMPLE).expect("parse");
        assert_eq!(table.winuxcmd_version.as_deref(), Some("1.2.0-dev"));
        assert_eq!(table.len(), 6);
        assert_eq!(table.lookup("cp").unwrap().tier, Tier::Tier1);
        assert_eq!(
            table.lookup("rm").unwrap().fallback_shapes,
            vec!["-i", "-I"]
        );
        assert_eq!(table.lookup("tee").unwrap().tier, Tier::Conditional);
        assert_eq!(table.lookup("wpm").unwrap().tier, Tier::Never);
        assert_eq!(table.lookup("arch").unwrap().tier, Tier::Spawn);
        assert!(table.lookup("nonexistent").is_none());
    }

    #[test]
    fn lookup_is_case_insensitive_with_canonical_spelling() {
        let table = TierTable::parse(SAMPLE).expect("parse");
        assert_eq!(table.lookup("GREP").unwrap().tier, Tier::Tier2);
        assert_eq!(table.canonical_name("GREP").as_deref(), Some("grep"));
        assert_eq!(table.canonical_name("grep").as_deref(), Some("grep"));
        assert_eq!(table.canonical_name("nope"), None);
    }

    #[test]
    fn malformed_lines_are_errors_not_panics() {
        assert!(TierTable::parse("grep\ttier9\t-\tx\n").is_err());
        assert!(TierTable::parse("grep\n").is_err());
    }

    #[test]
    fn short_flag_shapes_match_clusters() {
        let shapes = vec!["-i".to_string(), "-I".to_string()];
        let args = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        assert_eq!(matching_fallback_shape(&shapes, &args(&["-r", "x"])), None);
        assert_eq!(
            matching_fallback_shape(&shapes, &args(&["-ri", "x"])),
            Some("-i")
        );
        assert_eq!(matching_fallback_shape(&shapes, &args(&["-I"])), Some("-I"));
        // A long option never satisfies a short-flag shape.
        assert_eq!(
            matching_fallback_shape(&shapes, &args(&["--interactive"])),
            None
        );
    }

    #[test]
    fn long_shapes_match_exactly() {
        let shapes = vec!["--line-buffered".to_string()];
        let args = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        assert_eq!(
            matching_fallback_shape(&shapes, &args(&["--line-buffered"])),
            Some("--line-buffered")
        );
        assert_eq!(
            matching_fallback_shape(&shapes, &args(&["--line-bufferedx"])),
            None
        );
    }
}
